// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address to) public {
        // recipient must be a plain EOA that can receive ETH (no code, not a precompile)
        vm.assume(uint160(to) > 10);
        vm.assume(to.code.length == 0);
        amount = bound(amount, 1, 1 ether);

        address creator = address(this); // creator is whoever deployed c in setUp
        vm.deal(creator, amount);
        vm.prank(creator);
        c.deposit{value: amount}();

        vm.prank(creator);
        try c.migrateTo(to) {
            // Rule: after migrateTo, the contract holds no ETH.
            assertTrue(address(c).balance == 0, "migrateTo must drain contract balance");
        } catch {
            // transfer failed (recipient rejected) - reference may legitimately revert; balance stays
            assertTrue(true);
        }
    }
}
